1	import React, { useState, useEffect, useCallback, useRef } from 'react';
2	import {
3	  View,
4	  Text,
5	  StyleSheet,
6	  Pressable,
7	  FlatList,
8	  KeyboardAvoidingView,
9	  Platform,
10	  ActivityIndicator,
11	  Alert,
12	  ScrollView,
13	  AppState,
14	} from 'react-native';
15	import { useLocalSearchParams, router } from 'expo-router';
16	import { SafeAreaView } from 'react-native-safe-area-context';
17	import { Sprite, statusColor, statusDisplayName } from '@/models/sprite';
18	import { AgentProvider, ChatMessage, providerDisplayName, toolUseActivityLabel } from '@/models/chat';
19	import * as api from '@/services/api';
20	import { useChat } from '@/hooks/useChat';
21	import { useChatDictation } from '@/hooks/useChatDictation';
22	import { useTheme } from '@/hooks/use-theme';
23	import { ChatMessageView } from '@/components/chat/ChatMessageView';
24	import { ChatInputBar } from '@/components/chat/ChatInputBar';
25	import { ChatListSheet } from '@/components/chat/ChatListSheet';
26	import { NewSessionSheet, NewSessionConfig } from '@/components/chat/NewSessionSheet';
27	import { QuickBashSheet } from '@/components/chat/QuickBashSheet';
28	import { AgentSessionSummary, SessionBrowserSheet } from '@/components/chat/SessionBrowserSheet';
29	import { CheckpointsList } from '@/components/checkpoints/CheckpointsList';
30	import { SpriteAccountsTab } from '@/components/sprite/SpriteAccountsTab';
31	import { ActiveChatRun, PersistedChat, chatRepository } from '@/services/chat-repository';
32	import { getSetting, setSetting } from '@/services/storage';
33	import { TranscriptionProvider } from '@/services/client-transcription';
34	import { FontSize, Spacing } from '@/constants/theme';
35	import { DEFAULT_WORKING_DIRECTORY, normalizeWorkingDirectory, shortWorkingDirectory } from '@/constants/session';
36	
37	type Tab = 'overview' | 'chat' | 'accounts' | 'checkpoints';
38	
39	function normalizeProvider(provider: unknown): AgentProvider {
40	  return provider === 'codex' ? 'codex' : 'claude';
41	}
42	
43	function normalizeTranscriptionProvider(provider: unknown): TranscriptionProvider {
44	  return provider === 'assemblyai' || provider === 'openai' ? provider : 'sprite';
45	}
46	
47	/** Find the active tool label from the last assistant message's content */
48	function getActiveToolLabel(
49	  messages: ChatMessage[],
50	  workingDirectory: string
51	): string | undefined {
52	  for (let i = messages.length - 1; i >= 0; i--) {
53	    const msg = messages[i];
54	    if (msg.role !== 'assistant') continue;
55	    for (let j = msg.content.length - 1; j >= 0; j--) {
56	      const item = msg.content[j];
57	      if (item.type === 'toolUse' && !item.card.result) {
58	        return toolUseActivityLabel(item.card, workingDirectory);
59	      }
60	    }
61	    break;
62	  }
63	  return undefined;
64	}
65	
66	export default function SpriteDetailScreen() {
67	  const { name } = useLocalSearchParams<{ name: string }>();
68	  const colors = useTheme();
69	  const [tab, setTab] = useState<Tab>('chat');
70	  const [sprite, setSprite] = useState<Sprite | null>(null);
71	  const [isLoadingSprite, setIsLoadingSprite] = useState(true);
72	  const flatListRef = useRef<FlatList>(null);
73	
74	  // Multi-chat state
75	  const [chatId, setChatId] = useState<string>('');
76	  const [chatName, setChatName] = useState<string>('Session 1');
77	  const [chatProvider, setChatProvider] = useState<AgentProvider>('claude');
78	  const [claudeSessionId, setClaudeSessionId] = useState<string | undefined>();
79	  const [codexSessionId, setCodexSessionId] = useState<string | undefined>();
80	  const [activeRun, setActiveRun] = useState<ActiveChatRun | undefined>();
81	  const [chatListVisible, setChatListVisible] = useState(false);
82	  const [quickBashVisible, setQuickBashVisible] = useState(false);
83	  const [sessionBrowserVisible, setSessionBrowserVisible] = useState(false);
84	  // Bumped to force the current chat to reload its persisted messages (e.g. after
85	  // seeding a resumed session's transcript) even when chatId is unchanged.
86	  const [reloadNonce, setReloadNonce] = useState(0);
87	  // null = closed. 'new' creates a fresh session; 'edit' changes the current session's directory.
88	  const [sessionSheetMode, setSessionSheetMode] = useState<'new' | 'edit' | null>(null);
89	  const chatListRef = useRef<PersistedChat[]>([]);
90	  const appStateRef = useRef(AppState.currentState);
91	
92	  const spriteName = name ?? '';
93	  const [workingDirectory, setWorkingDirectory] = useState(DEFAULT_WORKING_DIRECTORY);
94	  const [defaultDirectory, setDefaultDirectory] = useState(DEFAULT_WORKING_DIRECTORY);
95	  const [transcriptionProvider, setTranscriptionProvider] =
96	    useState<TranscriptionProvider>('sprite');
97	
98	  const chat = useChat({
99	    spriteName,
100	    chatId,
101	    workingDirectory,
102	    provider: chatProvider,
103	    initialClaudeSessionId: claudeSessionId,
104	    initialCodexSessionId: codexSessionId,
105	    initialActiveRun: activeRun,
106	    onSessionIdsChange: (sessionIds) => {
107	      setClaudeSessionId(sessionIds.claudeSessionId);
108	      setCodexSessionId(sessionIds.codexSessionId);
109	      if (!chatId) return;
110	      const updated = chatListRef.current.map((chatMeta) =>
111	        chatMeta.id === chatId
112	          ? {
113	              ...chatMeta,
114	              claudeSessionId: sessionIds.claudeSessionId,
115	              codexSessionId: sessionIds.codexSessionId,
116	            }
117	          : chatMeta
118	      );
119	      chatListRef.current = updated;
120	      chatRepository.updateSessionIds(chatId, {
121	        claudeSessionId: sessionIds.claudeSessionId,
122	        codexSessionId: sessionIds.codexSessionId,
123	      });
124	    },
125	    onActiveRunChange: (nextActiveRun) => {
126	      setActiveRun(nextActiveRun);
127	      if (!chatId) return;
128	      const updated = chatListRef.current.map((chatMeta) =>
129	        chatMeta.id === chatId ? { ...chatMeta, activeRun: nextActiveRun } : chatMeta
130	      );
131	      chatListRef.current = updated;
132	      chatRepository.setActiveRun(chatId, nextActiveRun ?? undefined);
133	    },
134	  });
135	  const dictation = useChatDictation({
136	    spriteName,
137	    workingDirectory,
138	    inputText: chat.inputText,
139	    setInputText: chat.setInputText,
140	    transcriptionProvider,
141	  });
142	  const isProviderLocked = chat.messages.some((message) => message.role === 'user');
143	
144	  // Initialize chat list and current chat on mount
145	  useEffect(() => {
146	    let mounted = true;
147	    (async () => {
148	      const [chats, savedDefaultDir, savedTranscriptionProvider] = await Promise.all([
149	        chatRepository.listBySprite(spriteName),
150	        getSetting('defaultWorkingDirectory'),
151	        getSetting('transcriptionProvider'),
152	      ]);
153	      if (!mounted) return;
154	
155	      const fallbackDir = savedDefaultDir
156	        ? normalizeWorkingDirectory(savedDefaultDir)
157	        : DEFAULT_WORKING_DIRECTORY;
158	      setDefaultDirectory(fallbackDir);
159	      setTranscriptionProvider(normalizeTranscriptionProvider(savedTranscriptionProvider));
160	
161	      if (chats.length > 0) {
162	        chatListRef.current = chats;
163	        // Resume the most recently used session so reopening lands you right back in it.
164	        const sorted = [...chats].sort((a, b) => b.lastUsed - a.lastUsed);
165	        const current = sorted[0];
166	        setChatId(current.id);
167	        setChatName(current.customName ?? `Session ${current.chatNumber}`);
168	        setChatProvider(normalizeProvider(current.provider));
169	        setClaudeSessionId(current.claudeSessionId);
170	        setCodexSessionId(current.codexSessionId);
171	        setActiveRun(current.activeRun);
172	        setWorkingDirectory(current.workingDirectory || fallbackDir);
173	      } else {
174	        const defaultProvider = normalizeProvider(await getSetting('defaultProvider'));
175	        // Create the first chat
176	        const firstChat: PersistedChat = {
177	          id: `${spriteName}-chat-1`,
178	          spriteName,
179	          chatNumber: 1,
180	          provider: defaultProvider,
181	          workingDirectory: fallbackDir,
182	          createdAt: Date.now(),
183	          lastUsed: Date.now(),
184	          isClosed: false,
185	          lastSessionComplete: true,
186	          processedEventUUIDs: [],
187	        };
188	        chatListRef.current = [firstChat];
189	        await chatRepository.upsert(firstChat);
190	        setChatId(firstChat.id);
191	        setChatName('Session 1');
192	        setChatProvider(defaultProvider);
193	        setClaudeSessionId(undefined);
194	        setCodexSessionId(undefined);
195	        setActiveRun(undefined);
196	        setWorkingDirectory(fallbackDir);
197	      }
198	    })();
199	    return () => { mounted = false; };
200	  }, [spriteName]);
201	
202	  // Load sprite info
203	  useEffect(() => {
204	    let mounted = true;
205	    (async () => {
206	      try {
207	        const s = await api.getSprite(spriteName);
208	        if (mounted) setSprite(s);
209	      } catch {}
210	      if (mounted) setIsLoadingSprite(false);
211	    })();
212	    return () => { mounted = false; };
213	  }, [spriteName]);
214	
215	  // Old builds ran chat turns as persistent `wisp-*` services. Clean those up
216	  // when the sprite opens so they cannot restart and replay prompts into Claude.
217	  useEffect(() => {
218	    if (!spriteName) return;
219	    api.cleanupLegacyChatServices(spriteName).catch(() => {});
220	  }, [spriteName]);
221	
222	  // Load chat session when chatId changes (or when forced via reloadNonce).
223	  useEffect(() => {
224	    if (chatId) {
225	      chat.loadSession();
226	    }
227	    // eslint-disable-next-line react-hooks/exhaustive-deps
228	  }, [chatId, reloadNonce]);
229	
230	  // Re-sync the current chat whenever the app returns from the background or lock screen.
231	  // The hook will reattach to a still-running exec session, or merge the on-disk transcript
232	  // if the agent finished while the app was suspended.
233	  useEffect(() => {
234	    const subscription = AppState.addEventListener('change', (nextState) => {
235	      const wasAway =
236	        appStateRef.current === 'inactive' || appStateRef.current === 'background';
237	      appStateRef.current = nextState;
238	      if (nextState === 'active' && wasAway && chatId) {
239	        setReloadNonce((n) => n + 1);
240	      }
241	    });
242	
243	    return () => subscription.remove();
244	  }, [chatId]);
245	
246	  // Auto-scroll on new messages
247	  useEffect(() => {
248	    if (chat.messages.length > 0) {
249	      setTimeout(() => {
250	        flatListRef.current?.scrollToEnd({ animated: true });
251	      }, 100);
252	    }
253	  }, [chat.messages.length, chat.messages[chat.messages.length - 1]?.content.length]);
254	
255	  // Update chat list with first message preview when messages change
256	  useEffect(() => {
257	    if (chatId && chat.messages.length > 0) {
258	      const firstUserMsg = chat.messages.find((m) => m.role === 'user');
259	      if (firstUserMsg) {
260	        const preview = firstUserMsg.content
261	          .filter((c): c is { type: 'text'; text: string } => c.type === 'text')
262	          .map((c) => c.text)
263	          .join(' ')
264	          .slice(0, 100);
265	
266	        const updated = chatListRef.current.map((c) =>
267	          c.id === chatId
268	            ? { ...c, lastUsed: Date.now(), firstMessagePreview: preview || c.firstMessagePreview }
269	            : c
270	        );
271	        chatListRef.current = updated;
272	        chatRepository.patch(chatId, {
273	          lastUsed: Date.now(),
274	          firstMessagePreview: preview || undefined,
275	        });
276	      }
277	    }
278	  }, [chat.messages.length, chatId]);
279	
280	  const handleSend = () => {
281	    chat.sendMessage();
282	  };
283	
284	  const handleTranscriptionProviderChange = useCallback(async (provider: TranscriptionProvider) => {
285	    setTranscriptionProvider(provider);
286	    await setSetting('transcriptionProvider', provider);
287	  }, []);
288	
289	  const createChat = useCallback(async (config: NewSessionConfig) => {
290	    // One useChat instance is shared across sessions. Detach the local stream
291	    // before switching so the remote exec can keep running and be reattached later.
292	    if (chat.isStreaming) chat.detachStream();
293	    const chats = chatListRef.current;
294	    const maxNumber = chats.reduce((max, c) => Math.max(max, c.chatNumber), 0);
295	    const newNumber = maxNumber + 1;
296	    const dir = normalizeWorkingDirectory(config.workingDirectory);
297	    const newChat: PersistedChat = {
298	      id: `${spriteName}-chat-${newNumber}`,
299	      spriteName,
300	      chatNumber: newNumber,
301	      provider: config.provider,
302	      workingDirectory: dir,
303	      createdAt: Date.now(),
304	      lastUsed: Date.now(),
305	      isClosed: false,
306	      lastSessionComplete: true,
307	      processedEventUUIDs: [],
308	    };
309	    const updated = [...chats, newChat];
310	    chatListRef.current = updated;
311	    await chatRepository.upsert(newChat);
312	    setChatId(newChat.id);
313	    setChatName(`Session ${newNumber}`);
314	    setChatProvider(config.provider);
315	    setWorkingDirectory(dir);
316	    setClaudeSessionId(undefined);
317	    setCodexSessionId(undefined);
318	    setActiveRun(undefined);
319	    setChatListVisible(false);
320	    setSessionSheetMode(null);
321	  }, [chat.detachStream, chat.isStreaming, spriteName]);
322	
323	  // Change the directory of the *current* session (only allowed before its first message).
324	  const updateCurrentDirectory = useCallback(async (config: NewSessionConfig) => {
325	    const dir = normalizeWorkingDirectory(config.workingDirectory);
326	    setWorkingDirectory(dir);
327	    const updated = chatListRef.current.map((c) =>
328	      c.id === chatId ? { ...c, workingDirectory: dir } : c
329	    );
330	    chatListRef.current = updated;
331	    await chatRepository.patch(chatId, { workingDirectory: dir });
332	    setSessionSheetMode(null);
333	  }, [chatId, spriteName]);
334	
335	  const handleSelectChat = useCallback((selectedChat: PersistedChat) => {
336	    const latestChat = chatListRef.current.find((c) => c.id === selectedChat.id) ?? selectedChat;
337	    if (latestChat.id === chatId) {
338	      setReloadNonce((n) => n + 1);
339	      setChatListVisible(false);
340	      return;
341	    }
342	    // One useChat instance is shared across sessions, so detach any in-flight stream
343	    // before switching. The exec stays alive and is reattached when its chat reopens.
344	    if (chat.isStreaming) chat.detachStream();
345	    setChatId(latestChat.id);
346	    setChatName(latestChat.customName ?? `Session ${latestChat.chatNumber}`);
347	    setChatProvider(normalizeProvider(latestChat.provider));
348	    setClaudeSessionId(latestChat.claudeSessionId);
349	    setCodexSessionId(latestChat.codexSessionId);
350	    setActiveRun(latestChat.activeRun);
351	    setWorkingDirectory(latestChat.workingDirectory || defaultDirectory);
352	    setReloadNonce((n) => n + 1);
353	    // Update lastUsed
354	    const updated = chatListRef.current.map((c) =>
355	      c.id === latestChat.id ? { ...c, lastUsed: Date.now() } : c
356	    );
357	    chatListRef.current = updated;
358	    chatRepository.patch(latestChat.id, { lastUsed: Date.now() });
359	    setChatListVisible(false);
360	  }, [chat.detachStream, chat.isStreaming, chatId, spriteName, defaultDirectory]);
361	
362	  // Resume a session discovered on the sprite (its on-disk transcript).
363	  // Reuses an existing local chat bound to the same session id, or creates one,
364	  // seeds it with the rendered transcript, and points the chat at provider-specific
365	  // resume id with the session's original cwd when available.
366	  const handleResumeSession = useCallback(
367	    async (session: AgentSessionSummary, messages: ChatMessage[]) => {
368	      if (chat.isStreaming) chat.detachStream();
369	      const dir = normalizeWorkingDirectory(session.cwd || defaultDirectory);
370	      const chats = chatListRef.current;
371	      const existing = chats.find((c) =>
372	        session.provider === 'codex'
373	          ? c.provider === 'codex' && c.codexSessionId === session.id
374	          : c.provider === 'claude' && c.claudeSessionId === session.id
375	      );
376	
377	      let target: PersistedChat;
378	      if (existing) {
379	        target = {
380	          ...existing,
381	          provider: session.provider,
382	          claudeSessionId: session.provider === 'claude' ? session.id : existing.claudeSessionId,
383	          codexSessionId: session.provider === 'codex' ? session.id : existing.codexSessionId,
384	          workingDirectory: dir,
385	          lastUsed: Date.now(),
386	        };
387	      } else {
388	        const maxNumber = chats.reduce((max, c) => Math.max(max, c.chatNumber), 0);
389	        target = {
390	          id: `${spriteName}-chat-${maxNumber + 1}`,
391	          spriteName,
392	          chatNumber: maxNumber + 1,
393	          provider: session.provider,
394	          claudeSessionId: session.provider === 'claude' ? session.id : undefined,
395	          codexSessionId: session.provider === 'codex' ? session.id : undefined,
396	          workingDirectory: dir,
397	          createdAt: Date.now(),
398	          lastUsed: Date.now(),
399	          isClosed: false,
400	          lastSessionComplete: true,
401	          processedEventUUIDs: [],
402	          firstMessagePreview: session.preview ? session.preview.slice(0, 100) : undefined,
403	        };
404	      }
405	
406	      const updated = existing
407	        ? chats.map((c) => (c.id === target.id ? target : c))
408	        : [...chats, target];
409	      chatListRef.current = updated;
410	      await chatRepository.upsert(target);
411	      await chatRepository.setMessages(target.id, messages);
412	
413	      setChatProvider(session.provider);
414	      setClaudeSessionId(session.provider === 'claude' ? session.id : target.claudeSessionId);
415	      setCodexSessionId(session.provider === 'codex' ? session.id : target.codexSessionId);
416	      setActiveRun(undefined);
417	      setWorkingDirectory(dir);
418	      setChatName(target.customName ?? `Session ${target.chatNumber}`);
419	      setChatId(target.id);
420	      setSessionBrowserVisible(false);
421	      setTab('chat');
422	      // Force a reload even if chatId didn't change (resuming the open chat).
423	      setReloadNonce((n) => n + 1);
424	    },
425	    [chat.detachStream, chat.isStreaming, defaultDirectory, spriteName]
426	  );
427	
428	  const handleProviderChange = useCallback((nextProvider: AgentProvider) => {
429	    if (!chatId || chat.isStreaming || isProviderLocked) return;
430	    setChatProvider(nextProvider);
431	    const updated = chatListRef.current.map((c) =>
432	      c.id === chatId ? { ...c, provider: nextProvider } : c
433	    );
434	    chatListRef.current = updated;
435	    chatRepository.patch(chatId, { provider: nextProvider });
436	  }, [chat.isStreaming, chatId, isProviderLocked, spriteName]);
437	
438	  useEffect(() => {
439	    if (!chat.codexAuthIssue) return;
440	    const isLocked = isProviderLocked;
441	    Alert.alert(
442	      'Codex Authentication Required',
443	      isLocked
444	        ? `${chat.codexAuthIssue}\n\nThis session is locked to Codex. Start a new Claude session now?`
445	        : `${chat.codexAuthIssue}\n\nSwitch this session to Claude now?`,
446	      [
447	        {
448	          text: 'Cancel',
449	          style: 'cancel',
450	          onPress: () => chat.clearCodexAuthIssue(),
451	        },
452	        {
453	          text: isLocked ? 'New Claude Session' : 'Switch to Claude',
454	          onPress: () => {
455	            if (isLocked) {
456	              createChat({ workingDirectory, provider: 'claude' });
457	            } else {
458	              handleProviderChange('claude');
459	            }
460	            chat.clearCodexAuthIssue();
461	          },
462	        },
463	      ]
464	    );
465	  }, [chat.codexAuthIssue, chat.clearCodexAuthIssue, createChat, handleProviderChange, isProviderLocked, workingDirectory]);
466	
467	  const handleInsertBashOutput = useCallback((text: string) => {
468	    chat.setInputText((prev: string) => (prev ? prev + '\n' + text : text));
469	  }, [chat.setInputText]);
470	
471	  // Active tool label for the chat tab
472	  const activeToolLabel = chat.isStreaming
473	    ? getActiveToolLabel(chat.messages, workingDirectory)
474	    : undefined;
475	
476	  const tabItems: { key: Tab; label: string }[] = [
477	    { key: 'overview', label: 'Overview' },
478	    { key: 'chat', label: 'Chat' },
479	    { key: 'accounts', label: 'Accounts' },
480	    { key: 'checkpoints', label: 'Checkpoints' },
481	  ];
482	
483	  return (
484	    <SafeAreaView style={[styles.container, { backgroundColor: colors.background }]} edges={['top']}>
485	      {/* Header */}
486	      <View style={[styles.header, { borderBottomColor: colors.border }]}>
487	        <Pressable onPress={() => router.back()} hitSlop={12}>
488	          <Text style={[styles.backButton, { color: colors.tint }]}>&#x2039; Back</Text>
489	        </Pressable>
490	        <View style={styles.headerCenter}>
491	          <Text style={[styles.headerTitle, { color: colors.text }]} numberOfLines={1}>
492	            {spriteName}
493	          </Text>
494	          {sprite && tab !== 'chat' && (
495	            <View style={styles.statusRow}>
496	              <View
