// Options Tab — terminals, fast bash, and resuming previous sessions.
function OptionsTab({
  spriteName,
  workingDirectory,
  onQuickBash,
  onBrowseSessions,
}: {
  spriteName: string;
  workingDirectory: string;
  onQuickBash: () => void;
  onBrowseSessions: () => void;
}) {
